const std=@import("std");
pub fn main()!void{var gpa=std.heap.GeneralPurposeAllocator(.{}){};defer _=gpa.deinit();const al=gpa.allocator();const a=try std.process.argsAlloc(al);defer std.process.argsFree(al,a);if(a.len<2 or std.mem.eql(u8,a[1],"--help")){std.debug.print("Usage: hex-view FILE [LIMIT]\n",.{});if(a.len<2)std.process.exit(2);return;}var lim:usize=256;if(a.len>2)lim=try std.fmt.parseInt(usize,a[2],10);var f=try std.fs.cwd().openFile(a[1],.{});defer f.close();const d=try f.readToEndAlloc(al,lim);defer al.free(d);var i:usize=0;while(i<d.len):(i+=16){std.debug.print("{x:0>8}  ",.{i});var j:usize=0;while(j<16):(j+=1){if(i+j<d.len)std.debug.print("{x:0>2} ",.{d[i+j]})else std.debug.print("   ",.{});}std.debug.print(" ",.{});j=0;while(j<16 and i+j<d.len):(j+=1){const c=d[i+j];std.debug.print("{c}",.{if(c>=32 and c<=126)c else @as(u8,'.')});}std.debug.print("\n",.{});}}
